"use strict";(globalThis.webpackChunkn9e_site||=[]).push([[7283],{6401(e){e.exports=JSON.parse('{"version":{"pluginId":"integrations","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"integrations":[{"type":"link","label":"All integrations","href":"/integrations"},{"type":"category","label":"Hosts & hardware","collapsed":false,"items":[{"type":"link","href":"/integrations/linux","label":"Linux","docId":"linux","unlisted":false},{"type":"link","href":"/integrations/windows","label":"Windows","docId":"windows","unlisted":false},{"type":"link","href":"/integrations/systemd","label":"Systemd","docId":"systemd","unlisted":false},{"type":"link","href":"/integrations/smart","label":"SMART","docId":"smart","unlisted":false},{"type":"link","href":"/integrations/ipmi","label":"IPMI","docId":"ipmi","unlisted":false},{"type":"link","href":"/integrations/nvidia","label":"NVIDIA","docId":"nvidia","unlisted":false},{"type":"link","href":"/integrations/amd-rocm-smi","label":"AMD ROCm SMI","docId":"amd-rocm-smi","unlisted":false},{"type":"link","href":"/integrations/exec","label":"Exec","docId":"exec","unlisted":false}],"collapsible":true},{"type":"category","label":"Databases & storage","collapsed":false,"items":[{"type":"link","href":"/integrations/mysql","label":"MySQL","docId":"mysql","unlisted":false},{"type":"link","href":"/integrations/postgresql","label":"PostgreSQL","docId":"postgresql","unlisted":false},{"type":"link","href":"/integrations/redis","label":"Redis","docId":"redis","unlisted":false},{"type":"link","href":"/integrations/mongodb","label":"MongoDB","docId":"mongodb","unlisted":false},{"type":"link","href":"/integrations/oracle","label":"Oracle","docId":"oracle","unlisted":false},{"type":"link","href":"/integrations/sqlserver","label":"SQLServer","docId":"sqlserver","unlisted":false},{"type":"link","href":"/integrations/elasticsearch","label":"Elasticsearch","docId":"elasticsearch","unlisted":false},{"type":"link","href":"/integrations/clickhouse","label":"ClickHouse","docId":"clickhouse","unlisted":false},{"type":"link","href":"/integrations/doris","label":"Doris","docId":"doris","unlisted":false},{"type":"link","href":"/integrations/tidb","label":"TiDB","docId":"tidb","unlisted":false},{"type":"link","href":"/integrations/victoriametrics","label":"VictoriaMetrics","docId":"victoriametrics","unlisted":false}],"collapsible":true},{"type":"category","label":"Message queues","collapsed":false,"items":[{"type":"link","href":"/integrations/kafka","label":"Kafka","docId":"kafka","unlisted":false},{"type":"link","href":"/integrations/rabbitmq","label":"RabbitMQ","docId":"rabbitmq","unlisted":false},{"type":"link","href":"/integrations/nsq","label":"NSQ","docId":"nsq","unlisted":false},{"type":"link","href":"/integrations/emqx","label":"EMQX","docId":"emqx","unlisted":false},{"type":"link","href":"/integrations/automq","label":"AutoMQ","docId":"automq","unlisted":false}],"collapsible":true},{"type":"category","label":"Web & middleware","collapsed":false,"items":[{"type":"link","href":"/integrations/nginx","label":"Nginx","docId":"nginx","unlisted":false},{"type":"link","href":"/integrations/apache","label":"Apache","docId":"apache","unlisted":false},{"type":"link","href":"/integrations/haproxy","label":"HAProxy","docId":"haproxy","unlisted":false},{"type":"link","href":"/integrations/tomcat","label":"Tomcat","docId":"tomcat","unlisted":false},{"type":"link","href":"/integrations/java","label":"Java","docId":"java","unlisted":false},{"type":"link","href":"/integrations/springboot","label":"SpringBoot","docId":"springboot","unlisted":false},{"type":"link","href":"/integrations/php","label":"PHP","docId":"php","unlisted":false},{"type":"link","href":"/integrations/consul","label":"Consul","docId":"consul","unlisted":false},{"type":"link","href":"/integrations/ldap","label":"Ldap","docId":"ldap","unlisted":false},{"type":"link","href":"/integrations/bind","label":"Bind","docId":"bind","unlisted":false},{"type":"link","href":"/integrations/logstash","label":"Logstash","docId":"logstash","unlisted":false},{"type":"link","href":"/integrations/mtail","label":"Mtail","docId":"mtail","unlisted":false}],"collapsible":true},{"type":"category","label":"Containers & cloud native","collapsed":false,"items":[{"type":"link","href":"/integrations/kubernetes","label":"Kubernetes","docId":"kubernetes","unlisted":false},{"type":"link","href":"/integrations/docker","label":"Docker","docId":"docker","unlisted":false},{"type":"link","href":"/integrations/cadvisor","label":"cAdvisor","docId":"cadvisor","unlisted":false},{"type":"link","href":"/integrations/ceph","label":"Ceph","docId":"ceph","unlisted":false},{"type":"link","href":"/integrations/minio","label":"MinIO","docId":"minio","unlisted":false},{"type":"link","href":"/integrations/openstack","label":"OpenStack","docId":"openstack","unlisted":false},{"type":"link","href":"/integrations/vsphere","label":"vSphere","docId":"vsphere","unlisted":false}],"collapsible":true},{"type":"category","label":"Cloud providers & CDN","collapsed":false,"items":[{"type":"link","href":"/integrations/aliyun","label":"Alibaba Cloud","docId":"aliyun","unlisted":false},{"type":"link","href":"/integrations/huawei","label":"Huawei Cloud","docId":"huawei","unlisted":false},{"type":"link","href":"/integrations/tencent","label":"Tencent Cloud","docId":"tencent","unlisted":false},{"type":"link","href":"/integrations/cloudwatch","label":"CloudWatch","docId":"cloudwatch","unlisted":false},{"type":"link","href":"/integrations/azure","label":"Azure","docId":"azure","unlisted":false}],"collapsible":true},{"type":"category","label":"Network & probes","collapsed":false,"items":[{"type":"link","href":"/integrations/snmp","label":"SNMP","docId":"snmp","unlisted":false},{"type":"link","href":"/integrations/switch-legacy","label":"Switch (legacy)","docId":"switch-legacy","unlisted":false},{"type":"link","href":"/integrations/ping","label":"Ping","docId":"ping","unlisted":false},{"type":"link","href":"/integrations/net-response","label":"Net Response","docId":"net-response","unlisted":false},{"type":"link","href":"/integrations/dns-query","label":"DNS Query","docId":"dns-query","unlisted":false}],"collapsible":true},{"type":"category","label":"DevOps & others","collapsed":false,"items":[{"type":"link","href":"/integrations/gitlab","label":"Gitlab","docId":"gitlab","unlisted":false}],"collapsible":true}]},"docs":{"aliyun":{"id":"aliyun","title":"Monitor Alibaba Cloud with Nightingale","description":"Pulls ECS, RDS, Redis, SLB, CDN, ARMS and other product metrics through the CloudMonitor OpenAPI; the template ships dozens of per-product dashboards and rules.","sidebar":"integrations"},"amd-rocm-smi":{"id":"amd-rocm-smi","title":"Monitor AMD ROCm SMI with Nightingale","description":"Runs rocm-smi to collect AMD GPU utilization, memory, temperature, power and clocks; rules cover overheating and full memory.","sidebar":"integrations"},"apache":{"id":"apache","title":"Monitor Apache with Nightingale","description":"Reads the server-status?auto output of mod_status for request rate, busy and idle workers, CPU and traffic; rules watch worker exhaustion and unreachable servers.","sidebar":"integrations"},"automq":{"id":"automq","title":"Monitor AutoMQ with Nightingale","description":"AutoMQ exposes metrics through an OTel Collector or its own Prometheus endpoint; templates cover cluster overview, brokers, topics, consumer groups and detail.","sidebar":"integrations"},"azure":{"id":"azure","title":"Monitor Azure Monitor with Nightingale","description":"Pulls metrics per resource type through the Azure Monitor API, authenticating with a service principal that only needs the Monitoring Reader role.","sidebar":"integrations"},"bind":{"id":"bind","title":"Monitor BIND DNS with Nightingale","description":"Collects query counts, response codes, cache and memory contexts from BIND\'s statistics channel (XML v3); rules watch rising SERVFAIL and unreachable servers.","sidebar":"integrations"},"cadvisor":{"id":"cadvisor","title":"Monitor cAdvisor with Nightingale","description":"Scrapes the cAdvisor built into kubelet or a standalone one for per-container CPU, memory, filesystem and network metrics; in kubelet mode it can attach Pod labels and annotations.","sidebar":"integrations"},"ceph":{"id":"ceph","title":"Monitor Ceph with Nightingale","description":"Enable Ceph\'s prometheus mgr module and scrape port 9283; templates cover cluster health, OSDs, PGs, pool capacity and IOPS.","sidebar":"integrations"},"clickhouse":{"id":"clickhouse","title":"Monitor ClickHouse with Nightingale","description":"Reads system.metrics, system.events and system.asynchronous_metrics over HTTP; queries, merges, replication queues and memory all come with metric descriptions.","sidebar":"integrations"},"cloudwatch":{"id":"cloudwatch","title":"Monitor AWS CloudWatch with Nightingale","description":"Pulls metric statistics from any CloudWatch namespace through the API, so EC2, RDS, ELB and Lambda all fit; the template ships an RDS dashboard and common rules.","sidebar":"integrations"},"consul":{"id":"consul","title":"Monitor Consul with Nightingale","description":"Collects the health-check state of every registered service through the Consul API, so you see at once which service is critical or warning on which node.","sidebar":"integrations"},"dns-query":{"id":"dns-query","title":"Monitor DNS resolution quality with Nightingale","description":"Resolves a list of domains against the local or a named DNS server and reports query time, return code and record count, so slow or failing resolution shows up immediately.","sidebar":"integrations"},"docker":{"id":"docker","title":"Monitor Docker with Nightingale","description":"Collects per-container CPU, memory, block and network IO plus daemon state through the Docker API; the dashboard is written against docker_* metrics and verified on real hosts.","sidebar":"integrations"},"doris":{"id":"doris","title":"Monitor Doris with Nightingale","description":"FE and BE both expose Prometheus-format /metrics; scrape them with the Categraf prometheus input. Templates cover queries, loads, compaction and node state.","sidebar":"integrations"},"elasticsearch":{"id":"elasticsearch","title":"Monitor Elasticsearch with Nightingale","description":"Collects cluster health, node JVM, thread pools, index and shard state through Elasticsearch\'s own HTTP API; one node is enough to see the whole cluster on small deployments.","sidebar":"integrations"},"emqx":{"id":"emqx","title":"Monitor EMQX with Nightingale","description":"Collects node state, connections, subscriptions, message throughput and drops through the EMQX Dashboard API; supports v3, v4 and v5.","sidebar":"integrations"},"exec":{"id":"exec","title":"Report custom metrics to Nightingale from scripts (Exec)","description":"For anything no plugin covers: write a script that prints Prometheus, InfluxDB line protocol or Open-Falcon format to stdout, and Categraf collects and ships it.","sidebar":"integrations"},"gitlab":{"id":"gitlab","title":"Monitor GitLab with Nightingale","description":"The GitLab package bundles several exporters for the host, Rails/Sidekiq, Gitaly, Workhorse, PostgreSQL, Redis and NGINX; the template ships five dashboards.","sidebar":"integrations"},"haproxy":{"id":"haproxy","title":"Monitor HAProxy with Nightingale","description":"Reads HAProxy\'s CSV stats page or Runtime API for sessions, queues, errors and health state per frontend, backend and server.","sidebar":"integrations"},"huawei":{"id":"huawei","title":"Monitor Huawei Cloud with Nightingale","description":"Scrape Cloud Eye (CES) metrics converted to Prometheus format by the cloudeye-exporter; templates cover ECS, RDS, DCS, ELB, Kafka, RocketMQ, CSS and WAF.","sidebar":"integrations"},"ipmi":{"id":"ipmi","title":"Monitor IPMI with Nightingale","description":"Reads out-of-band temperature, fan, voltage, power and sensor state over IPMI, from the local BMC or remote ones.","sidebar":"integrations"},"java":{"id":"java","title":"Monitor Java applications (JVM) with Nightingale","description":"JVM memory, GC, threads and class loading exposed via the JMX Exporter or the OpenTelemetry Java Agent; one dashboard set for each metric naming.","sidebar":"integrations"},"kafka":{"id":"kafka","title":"Monitor Kafka with Nightingale","description":"Broker metrics come from JMX, consumer lag from the embedded kafka_exporter logic; templates come in Categraf and exporter editions, rules watch lag, offline partitions and shrinking ISR.","sidebar":"integrations"},"kubernetes":{"id":"kubernetes","title":"Monitor Kubernetes with Nightingale","description":"Scrapes the native /metrics of the apiserver, kubelet, controller-manager, scheduler, kube-proxy, CoreDNS, kube-state-metrics and node-exporter; templates cover every layer from control plane to Pod.","sidebar":"integrations"},"ldap":{"id":"ldap","title":"Monitor LDAP (OpenLDAP, 389ds) with Nightingale","description":"Reads the LDAP server\'s cn=Monitor backend for connections, operation counters, waiters and thread state; supports OpenLDAP and 389 Directory Server.","sidebar":"integrations"},"linux":{"id":"linux","title":"Monitor Linux with Nightingale","description":"CPU, memory, disk, network, processes and kernel parameters out of the box; templates cover Categraf, node_exporter and Telegraf metric names.","sidebar":"integrations"},"logstash":{"id":"logstash","title":"Monitor Logstash with Nightingale","description":"Collects pipeline event in/out and filter time, queue state and JVM health from Logstash\'s node API; rules watch event backlog and JVM pressure.","sidebar":"integrations"},"minio":{"id":"minio","title":"Monitor MinIO with Nightingale","description":"MinIO ships a Prometheus endpoint; scrape the cluster, bucket and node paths together or the object, bucket, process and disk panels stay empty.","sidebar":"integrations"},"mongodb":{"id":"mongodb","title":"Monitor MongoDB with Nightingale","description":"Embeds the mongodb_exporter collector for connections, op counters, replica set and sharding state; the dashboards need the compatible metric names turned on.","sidebar":"integrations"},"mtail":{"id":"mtail","title":"Turn logs into Nightingale metrics with mtail","description":"Categraf embeds mtail: extract counters, gauges and histograms from log files with regular expressions and expressions, without shipping the logs to a log system first.","sidebar":"integrations"},"mysql":{"id":"mysql","title":"Monitor MySQL with Nightingale","description":"Connects to the instance and runs SHOW STATUS, SHOW VARIABLES and replica status; slow-query pileups, connection exhaustion and broken or lagging replication come with rules and runbooks.","sidebar":"integrations"},"net-response":{"id":"net-response","title":"TCP/UDP port probes with Nightingale","description":"Checks whether a local or remote port accepts connections and responds as expected; result codes 0 to 4 mean success, timeout, connection failure, read failure and content mismatch.","sidebar":"integrations"},"nginx":{"id":"nginx","title":"Monitor Nginx with Nightingale","description":"stub_status covers connections and request totals, the VTS module adds per-server and per-upstream status codes and latency; an upstream_check input reads health-check results.","sidebar":"integrations"},"nsq":{"id":"nsq","title":"Monitor NSQ with Nightingale","description":"Reads nsqd\'s /stats endpoint for per-topic and per-channel depth, in-flight, timeouts and client counts; rules watch growing backlog and lost consumers.","sidebar":"integrations"},"nvidia":{"id":"nvidia","title":"Monitor NVIDIA with Nightingale","description":"Two ways to collect NVIDIA GPUs: nvidia-smi is light and usually enough, DCGM gives more; dashboards cover a fleet overview, single cards and training jobs.","sidebar":"integrations"},"openstack":{"id":"openstack","title":"Monitor OpenStack with Nightingale","description":"Collects resources and quotas from Nova, Neutron, Cinder, Glance, Keystone and Heat through the OpenStack API, plus the state of every instance.","sidebar":"integrations"},"oracle":{"id":"oracle","title":"Monitor Oracle with Nightingale","description":"Runs a customizable set of SQL queries with a read-only account to collect sessions, tablespaces, wait events and cache hit ratios; a Linux Categraf can monitor Oracle on Windows remotely.","sidebar":"integrations"},"php":{"id":"php","title":"Monitor PHP-FPM with Nightingale","description":"With pm.status_path enabled, the input reads the PHP-FPM pool status over HTTP or a Unix socket: active and idle processes, request queue, slow requests and max-children hits.","sidebar":"integrations"},"ping":{"id":"ping","title":"Ping probes with Nightingale","description":"Ping a list of targets from wherever Categraf runs and get packet loss, round-trip latency and jitter; the simplest liveness check there is.","sidebar":"integrations"},"postgresql":{"id":"postgresql","title":"Monitor PostgreSQL with Nightingale","description":"Collects connections, transactions, cache hit ratio, locks and replication state with a read-only pg_monitor account; custom queries against business tables are supported.","sidebar":"integrations"},"rabbitmq":{"id":"rabbitmq","title":"Monitor RabbitMQ with Nightingale","description":"On 3.8+ scrape the built-in Prometheus plugin on port 15692; older versions go through the management API. Templates are split by version; rules watch queue backlog, unacked messages and node state.","sidebar":"integrations"},"redis":{"id":"redis","title":"Monitor Redis with Nightingale","description":"Runs INFO against Redis to collect memory, hit ratio, connections, slowlog and replication state; includes a Sentinel input and templates for redis_exporter.","sidebar":"integrations"},"smart":{"id":"smart","title":"Monitor SMART with Nightingale","description":"Runs smartctl to read S.M.A.R.T. health attributes from HDDs, SSDs and NVMe drives, so you see reallocated sectors, temperature and wear before a disk actually dies.","sidebar":"integrations"},"snmp":{"id":"snmp","title":"Monitor network devices over SNMP with Nightingale","description":"Collect any network device by listing OIDs, with OID values usable as labels; the template ships Cisco, Juniper and generic switch dashboards and dozens of rules.","sidebar":"integrations"},"springboot":{"id":"springboot","title":"Monitor Spring Boot applications with Nightingale","description":"Add Actuator and micrometer-registry-prometheus and the application exposes /actuator/prometheus itself; the template ships JVM dashboards split by application name.","sidebar":"integrations"},"sqlserver":{"id":"sqlserver","title":"Monitor SQLServer with Nightingale","description":"Collects connections, waits, buffer pool, log usage and database state from DMVs and performance counters; VIEW SERVER STATE is all the permission it needs.","sidebar":"integrations"},"switch-legacy":{"id":"switch-legacy","title":"Monitor switches with zero config (Switch Legacy) in Nightingale","description":"Give it a list of IPs and it detects the device model and collects CPU, memory and per-port traffic, errors and state; SNMP v2c only.","sidebar":"integrations"},"systemd":{"id":"systemd","title":"Monitor Systemd with Nightingale","description":"Reads systemd unit state, restart counts and startup time over D-Bus, so failed or flapping services page you right away.","sidebar":"integrations"},"tencent":{"id":"tencent","title":"Monitor Tencent Cloud with Nightingale","description":"Scrape Cloud Monitor metrics converted to Prometheus format by the tencentcloud-exporter; templates cover CVM, CKafka, PostgreSQL, Redis, TDSQL-C and load balancers.","sidebar":"integrations"},"tidb":{"id":"tidb","title":"Monitor TiDB with Nightingale","description":"TiDB, PD and TiKV all expose Prometheus metrics on /metrics; the templates cover SQL latency, Region scheduling, storage and node health.","sidebar":"integrations"},"tomcat":{"id":"tomcat","title":"Monitor Tomcat with Nightingale","description":"Reads the /manager/status/all endpoint of the Manager app for JVM memory, per-connector threads and requests, traffic and errors; needs the manager-gui role.","sidebar":"integrations"},"victoriametrics":{"id":"victoriametrics","title":"Monitor VictoriaMetrics with Nightingale","description":"Both the single-node and cluster editions expose /metrics; templates cover vmsingle as well as the vmstorage, vmselect and vminsert cluster components.","sidebar":"integrations"},"vsphere":{"id":"vsphere","title":"Monitor vSphere with Nightingale","description":"Pulls CPU, memory, disk and network performance counters for ESXi hosts, virtual machines, datastores and clusters through the vCenter API.","sidebar":"integrations"},"windows":{"id":"windows","title":"Monitor Windows with Nightingale","description":"Categraf reports the same metric names on Windows as on Linux, so host dashboards and rules carry over; extra dashboards cover AD, DNS and ADFS via windows_exporter.","sidebar":"integrations"}}}}')}}]);